/**
 * The parts of scipy.signal the monitor uses, written out for the phone:
 * Butterworth design as second-order sections, sosfilt with state, sosfilt_zi,
 * find_peaks (height + distance), detrend, Hann window and a real FFT.
 *
 * Checked against scipy in __tests__/signal.test.ts using vectors generated by
 * scripts/make_dsp_vectors.py.
 */

/** One biquad: [b0, b1, b2, a0, a1, a2] with a0 = 1, as in scipy's sos rows. */
export type Sos = number[][];

type C = { re: number; im: number };
const c = (re: number, im = 0): C => ({ re, im });
const add = (a: C, b: C) => c(a.re + b.re, a.im + b.im);
const sub = (a: C, b: C) => c(a.re - b.re, a.im - b.im);
const mul = (a: C, b: C) => c(a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re);
const div = (a: C, b: C) => {
  const d = b.re * b.re + b.im * b.im;
  return c((a.re * b.re + a.im * b.im) / d, (a.im * b.re - a.re * b.im) / d);
};
const scale = (a: C, k: number) => c(a.re * k, a.im * k);
const csqrt = (a: C): C => {
  const r = Math.hypot(a.re, a.im);
  const re = Math.sqrt((r + a.re) / 2);
  const im = Math.sign(a.im || 1) * Math.sqrt(Math.max(0, (r - a.re) / 2));
  return c(re, a.im === 0 && a.re >= 0 ? 0 : im);
};

export type FilterKind = 'lowpass' | 'highpass' | 'bandpass';

/**
 * Digital Butterworth filter as second-order sections, matching
 * scipy.signal.butter(order, Wn, btype, fs=fs, output='sos') in response.
 * Frequencies in Hz.
 */
export function butterSos(order: number, freqs: number | [number, number], kind: FilterKind, fs: number): Sos {
  const fs2 = 2 * fs;
  const warp = (f: number) => fs2 * Math.tan((Math.PI * f) / fs);

  // Analog low-pass prototype poles, cutoff 1 rad/s.
  const proto: C[] = [];
  for (let k = 0; k < order; k++) {
    const theta = (Math.PI * (2 * k + order + 1)) / (2 * order);
    proto.push(c(Math.cos(theta), Math.sin(theta)));
  }

  let poles: C[] = [];
  let zerosAtDc = 0; // analog zeros at s = 0 -> z = +1
  let zerosAtInf = 0; // analog zeros at infinity -> z = -1
  let normAt: number; // digital frequency (rad/sample) where gain is set to 1

  if (kind === 'lowpass') {
    const wc = warp(freqs as number);
    poles = proto.map((p) => scale(p, wc));
    zerosAtInf = order;
    normAt = 0;
  } else if (kind === 'highpass') {
    const wc = warp(freqs as number);
    poles = proto.map((p) => div(c(wc), p));
    zerosAtDc = order;
    normAt = Math.PI;
  } else {
    const [f1, f2] = freqs as [number, number];
    const w1 = warp(f1);
    const w2 = warp(f2);
    const bw = w2 - w1;
    const w0sq = w1 * w2;
    for (const p of proto) {
      const half = scale(p, bw / 2);
      const root = csqrt(sub(mul(half, half), c(w0sq)));
      poles.push(add(half, root), sub(half, root));
    }
    zerosAtDc = order;
    zerosAtInf = order;
    // Peak of the band-pass is at the centre frequency sqrt(w1 w2) (analog).
    normAt = 2 * Math.atan(Math.sqrt(w0sq) / fs2);
  }

  // Bilinear transform of the poles.
  const zPoles = poles.map((p) => div(add(c(fs2), p), sub(c(fs2), p)));

  // Pair poles into conjugate pairs (upper half-plane representatives) and reals.
  const used = new Array(zPoles.length).fill(false);
  const pairs: [C, C | null][] = [];
  const reals: C[] = [];
  const tol = 1e-9;
  for (let i = 0; i < zPoles.length; i++) {
    if (used[i]) continue;
    const p = zPoles[i];
    used[i] = true;
    if (Math.abs(p.im) < tol) {
      reals.push(c(p.re));
      continue;
    }
    let best = -1;
    let bestD = Infinity;
    for (let j = 0; j < zPoles.length; j++) {
      if (used[j]) continue;
      const d = Math.hypot(zPoles[j].re - p.re, zPoles[j].im + p.im);
      if (d < bestD) {
        bestD = d;
        best = j;
      }
    }
    used[best] = true;
    pairs.push([p, zPoles[best]]);
  }
  for (let i = 0; i + 1 < reals.length; i += 2) pairs.push([reals[i], reals[i + 1]]);
  if (reals.length % 2) pairs.push([reals[reals.length - 1], null]);

  // Hand out the digital zeros (+1 and -1) to the sections.
  const zeroList: number[] = [];
  for (let i = 0; i < zerosAtDc; i++) zeroList.push(1);
  for (let i = 0; i < zerosAtInf; i++) zeroList.push(-1);
  // For band-pass give each section one of each, which keeps sections well scaled.
  zeroList.sort((a, b) => b - a);
  const interleaved: number[] = [];
  const plus = zeroList.filter((z) => z > 0);
  const minus = zeroList.filter((z) => z < 0);
  while (plus.length || minus.length) {
    if (plus.length) interleaved.push(plus.shift() as number);
    if (minus.length) interleaved.push(minus.shift() as number);
  }

  const sos: Sos = [];
  let zi = 0;
  for (const [p1, p2] of pairs) {
    let a: number[];
    if (p2 === null) a = [1, -p1.re, 0];
    else {
      const sum = add(p1, p2);
      const prod = mul(p1, p2);
      a = [1, -sum.re, prod.re];
    }
    const order2 = p2 === null ? 1 : 2;
    const zs = interleaved.slice(zi, zi + order2);
    zi += order2;
    let b: number[];
    if (zs.length === 2) b = [1, -(zs[0] + zs[1]), zs[0] * zs[1]];
    else if (zs.length === 1) b = [1, -zs[0], 0];
    else b = [1, 0, 0];
    sos.push([...b, ...a]);
  }

  // Overall gain so |H(e^{j normAt})| = 1, applied to the first section.
  const z = c(Math.cos(normAt), Math.sin(normAt));
  const z1 = div(c(1), z);
  const z2 = mul(z1, z1);
  let h = c(1);
  for (const s of sos) {
    const num = add(add(c(s[0]), scale(z1, s[1])), scale(z2, s[2]));
    const den = add(add(c(s[3]), scale(z1, s[4])), scale(z2, s[5]));
    h = mul(h, div(num, den));
  }
  const k = 1 / Math.hypot(h.re, h.im);
  sos[0][0] *= k;
  sos[0][1] *= k;
  sos[0][2] *= k;
  return sos;
}

/** Steady-state state for a unit step, as scipy.signal.sosfilt_zi. Shape [n_sections][2]. */
export function sosfiltZi(sos: Sos): number[][] {
  const zi: number[][] = [];
  let scaleK = 1;
  for (const [b0, b1, b2, , a1, a2] of sos) {
    // scipy lfilter_zi: IminusA = I - companion(a).T, B = b[1:] - a[1:] * b0.
    // companion([1, a1, a2]) = [[-a1, -a2], [1, 0]], so IminusA = [[1 + a1, -1], [a2, 1]].
    const B0 = b1 - a1 * b0;
    const B1 = b2 - a2 * b0;
    const m00 = 1 + a1;
    const m01 = -1;
    const m10 = a2;
    const m11 = 1;
    const det = m00 * m11 - m01 * m10;
    const z0 = (B0 * m11 - m01 * B1) / det;
    const z1 = (m00 * B1 - m10 * B0) / det;
    zi.push([z0 * scaleK, z1 * scaleK]);
    scaleK *= (b0 + b1 + b2) / (1 + a1 + a2);
  }
  return zi;
}

/** Direct-form II transposed cascade, as scipy.signal.sosfilt. Mutates zi when given. */
export function sosfilt(sos: Sos, x: ArrayLike<number>, zi?: number[][]): Float64Array {
  const y = Float64Array.from(x as ArrayLike<number>);
  for (let s = 0; s < sos.length; s++) {
    const [b0, b1, b2, , a1, a2] = sos[s];
    let z0 = zi ? zi[s][0] : 0;
    let z1 = zi ? zi[s][1] : 0;
    for (let n = 0; n < y.length; n++) {
      const xn = y[n];
      const yn = b0 * xn + z0;
      z0 = b1 * xn - a1 * yn + z1;
      z1 = b2 * xn - a2 * yn;
      y[n] = yn;
    }
    if (zi) {
      zi[s][0] = z0;
      zi[s][1] = z1;
    }
  }
  return y;
}

/**
 * scipy.signal.find_peaks(x, height=h, distance=d): local maxima (flat tops
 * resolved to their middle), at least `height`, and no two closer than
 * `distance` samples with the taller one kept.
 */
export function findPeaks(x: ArrayLike<number>, height: number, distance: number): number[] {
  const n = x.length;
  let peaks: number[] = [];
  let i = 1;
  const iMax = n - 1;
  while (i < iMax) {
    if (x[i - 1] < x[i]) {
      let ahead = i + 1;
      while (ahead < iMax && x[ahead] === x[i]) ahead++;
      if (x[ahead] < x[i]) {
        const left = i;
        const right = ahead - 1;
        peaks.push(Math.floor((left + right) / 2));
        i = ahead;
      }
    }
    i++;
  }
  peaks = peaks.filter((p) => x[p] >= height);
  if (distance > 1 && peaks.length > 1) {
    const keep = new Array(peaks.length).fill(true);
    // Order by height. Exact ties between separate peaks are ordered by numpy's
    // argsort in an implementation-defined way; here the earlier peak wins.
    const order = peaks.map((_, k) => k).sort((a, b) => x[peaks[a]] - x[peaks[b]] || b - a);
    for (let oi = order.length - 1; oi >= 0; oi--) {
      const j = order[oi];
      if (!keep[j]) continue;
      let k = j - 1;
      while (k >= 0 && peaks[j] - peaks[k] < distance) keep[k--] = false;
      k = j + 1;
      while (k < peaks.length && peaks[k] - peaks[j] < distance) keep[k++] = false;
    }
    peaks = peaks.filter((_, k) => keep[k]);
  }
  return peaks;
}

export function median(x: ArrayLike<number>): number {
  const s = Array.from(x).sort((a, b) => a - b);
  const n = s.length;
  if (!n) return NaN;
  return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
}
export function mean(x: ArrayLike<number>): number {
  let s = 0;
  for (let i = 0; i < x.length; i++) s += x[i];
  return s / x.length;
}
/** Population standard deviation, as numpy.std. */
export function std(x: ArrayLike<number>): number {
  const m = mean(x);
  let s = 0;
  for (let i = 0; i < x.length; i++) s += (x[i] - m) ** 2;
  return Math.sqrt(s / x.length);
}

/** Remove the least-squares line, as scipy.signal.detrend (type='linear'). */
export function detrend(x: ArrayLike<number>): Float64Array {
  const n = x.length;
  const out = new Float64Array(n);
  if (n === 0) return out;
  let st = 0, sx = 0, stt = 0, stx = 0;
  for (let i = 0; i < n; i++) {
    st += i;
    sx += x[i];
    stt += i * i;
    stx += i * x[i];
  }
  const d = n * stt - st * st;
  const slope = d === 0 ? 0 : (n * stx - st * sx) / d;
  const icpt = (sx - slope * st) / n;
  for (let i = 0; i < n; i++) out[i] = x[i] - (icpt + slope * i);
  return out;
}

/** numpy.hanning (symmetric). */
export function hanning(n: number): Float64Array {
  const w = new Float64Array(n);
  if (n === 1) {
    w[0] = 1;
    return w;
  }
  for (let i = 0; i < n; i++) w[i] = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
  return w;
}

/** |rfft(x, nfft)|^2 for nfft a power of two. Returns nfft/2 + 1 bins. */
export function powerSpectrum(x: ArrayLike<number>, nfft: number): Float64Array {
  const re = new Float64Array(nfft);
  const im = new Float64Array(nfft);
  for (let i = 0; i < Math.min(x.length, nfft); i++) re[i] = x[i];
  // Iterative radix-2 FFT.
  for (let i = 1, j = 0; i < nfft; i++) {
    let bit = nfft >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= nfft; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    const wr = Math.cos(ang);
    const wi = Math.sin(ang);
    for (let i = 0; i < nfft; i += len) {
      let cr = 1, ci = 0;
      for (let k = 0; k < len / 2; k++) {
        const a = i + k;
        const b = a + len / 2;
        const tr = re[b] * cr - im[b] * ci;
        const ti = re[b] * ci + im[b] * cr;
        re[b] = re[a] - tr;
        im[b] = im[a] - ti;
        re[a] += tr;
        im[a] += ti;
        const ncr = cr * wr - ci * wi;
        ci = cr * wi + ci * wr;
        cr = ncr;
      }
    }
  }
  const out = new Float64Array(nfft / 2 + 1);
  for (let k = 0; k <= nfft / 2; k++) out[k] = re[k] * re[k] + im[k] * im[k];
  return out;
}
